class Solution:
    def minimumRightShifts(self, nums: List[int]) -> int:
        n = len(nums)
        if n == 1:
            return 0

        # Find the number of "breaks" where nums[i] > nums[i+1]
        breaks = []
        for i in range(n):
            if nums[i] > nums[(i + 1) % n]:
                breaks.append(i)

        # For a valid rotation, there should be exactly one break
        if len(breaks) != 1:
            return -1

        # The break is at index breaks[0], meaning nums[breaks[0]] > nums[(breaks[0]+1) % n]
        # The sorted array would start at index (breaks[0] + 1) % n
        # The number of right shifts needed is the number of elements from the start to the break
        # i.e., breaks[0] + 1
        return breaks[0] + 1
```

