        # right[i][j] = set of possible OR values when choosing j elements from nums[i..n-1]

        # Then for each split point, we combine left and right.

        # Actually, we need to be careful: the subsequence is of size 2*k, split into two halves of size k.
        # The first half is some k elements, the second half is some k elements, and the first half elements
        # must come before the second half elements in the original array? 
        # Wait, the problem says "subsequence", so order is preserved. But the value definition splits the
        # subsequence into first k and last k. So we need to choose 2k elements in order, and the first k
        # form one group, the last k form another group.

        # So we can think: for each possible split index s (0 <= s <= n), we choose k elements from nums[0..s-1]
        # and k elements from nums[s..n-1]. But actually, the split in the subsequence doesn't have to align
        # with a single index in the original array. However, since it's a subsequence, there exists a boundary
        # in the original array such that all first-half elements are before all second-half elements.
        # Specifically, if the subsequence is indices i1 < i2 < ... < i_{2k}, then the first half is i1..ik
        # and second half is i_{k+1}..i_{2k}. So all first half indices are less than all second half indices.
        # Therefore, we can iterate over the split point: for each position p (0 to n), consider choosing k
        # elements from nums[0..p-1] and k elements from nums[p..n-1].

        # Precompute left[p][j] = set of OR values for choosing j elements from nums[0..p-1]
        # Precompute right[p][j] = set of OR values for choosing j elements from nums[p..n-1]

        # left[0][0] = {0}
        # left[p][j] = union of:
        #   left[p-1][j]  (don't take nums[p-1])
        #   {v | nums[p-1] for v in left[p-1][j-1]}  (take nums[p-1])

        # Similarly for right.

        left = [[set() for _ in range(k+1)] for _ in range(n+1)]
        left[0][0] = {0}
        for i in range(1, n+1):
            for j in range(k+1):
                # Don't take nums[i-1]
                if j <= i-1:
                    left[i][j] |= left[i-1][j]
                # Take nums[i-1]
                if j > 0 and j-1 <= i-1:
                    for v in left[i-1][j-1]:
                        left[i][j].add(v | nums[i-1])

        right = [[set() for _ in range(k+1)] for _ in range(n+1)]
        right[n][0] = {0}
        for i in range(n-1, -1, -1):
            for j in range(k+1):
                # Don't take nums[i]
                if j <= n-1-i:
                    right[i][j] |= right[i+1][j]
                # Take nums[i]
                if j > 0 and j-1 <= n-1-i:
                    for v in right[i+1][j-1]:
                        right[i][j].add(v | nums[i])

        ans = 0
        for p in range(n+1):
            for a in left[p][k]:
                for b in right[p][k]:
                    val = a ^ b
                    if val > ans:
                        ans = val
        return ans
