    # The problem says "It is fine to have unused tiles", so we need to find a subset
    # of the given tiles that can exactly cover the H x W grid.

    # For each subset of tiles, check if they can tile the H x W grid.
    # For a fixed subset, we need to check if the tiles can be arranged to cover the grid.
    # This is a 2D tiling problem. Since H, W <= 10 and the number of tiles in a subset is small,
    # we can use backtracking with bitmask or recursive placement.

    # However, a simpler approach: for a given set of tiles, the total area must equal H*W.
    # Then we need to check if they can actually tile the grid.

    # Let's use a recursive backtracking approach for each subset.
    # But first, let's filter subsets by area.

    n = len(tiles)
    total_area = H * W

    # Try all non-empty subsets
    for r in range(1, n + 1):
        for subset in combinations(range(n), r):
            # Check area
            area = 0
            for idx in subset:
                a, b = tiles[idx]
                area += a * b
            if area != total_area:
                continue

            # Now check if this subset can tile the H x W grid
            if can_tile(tiles, subset, H, W):
                return True

    return False

def can_tile(tiles, subset, H, W):
    """
    Check if the tiles in the given subset can exactly tile an H x W grid.
    Each tile can be rotated.
    """
    # Create a list of the actual tiles in the subset
    tile_list = []
    for idx in subset:
        a, b = tiles[idx]
        tile_list.append((a, b))

    # Use backtracking to place tiles
    # State: grid (H x W), list of remaining tiles
    # We'll represent the grid as a 2D list of booleans (True if covered)
    # Or better, use a bitmask if H*W is small enough. H*W <= 100, so bitmask with 100 bits is feasible but Python ints can handle it.

    # Let's use a recursive approach with a grid representation.
    # To optimize, we'll always place the next tile at the first empty cell (scanning row by row).

    grid = [[False] * W for _ in range(H)]
    remaining = list(tile_list)

    def backtrack():
        # Find the first empty cell
        for i in range(H):
            for j in range(W):
                if not grid[i][j]:
                    # Try to place each remaining tile at (i, j)
                    for k in range(len(remaining)):
                        a, b = remaining[k]
                        # Try orientation 1: a x b
                        if i + a <= H and j + b <= W:
                            # Check if all cells are empty
                            can_place_here = True
                            for di in range(a):
                                for dj in range(b):
                                    if grid[i + di][j + dj]:
                                        can_place_here = False
                                        break
                                if not can_place_here:
                                    break
                            if can_place_here:
                                # Place the tile
                                for di in range(a):
                                    for dj in range(b):
                                        grid[i + di][j + dj] = True
                                remaining.pop(k)
                                if backtrack():
                                    return True
                                remaining.insert(k, (a, b))
                                for di in range(a):
                                    for dj in range(b):
                                        grid[i + di][j + dj] = False

                        # Try orientation 2: b x a (if different)
                        if a != b:
                            if i + b <= H and j + a <= W:
                                can_place_here = True
                                for di in range(b):
                                    for dj in range(a):
                                        if grid[i + di][j + dj]:
                                            can_place_here = False
                                            break
                                    if not can_place_here:
