                                    remaining.insert(k, (a, b))
                                    for di in range(b):
                                        for dj in range(a):
                                            grid[i + di][j + dj] = False
                    return False  # No tile could be placed at this cell
        # All cells are covered
        return len(remaining) == 0

    return backtrack()

