    def numberOfChild(self, n: int, k: int) -> int:
        # The ball moves in a pattern: 0, 1, 2, ..., n-1, n-2, ..., 1, 0, 1, ...
        # The period of the pattern is 2*(n-1)
        # We can compute the position after k seconds using modulo

