class Solution:
    def maximumOr(self, nums: List[int], k: int) -> int:
        n = len(nums)
        # Compute prefix ORs and suffix ORs
        prefix_or = [0] * n
        suffix_or = [0] * n

        prefix_or[0] = nums[0]
        for i in range(1, n):
            prefix_or[i] = prefix_or[i-1] | nums[i]

        suffix_or[n-1] = nums[n-1]
        for i in range(n-2, -1, -1):
            suffix_or[i] = suffix_or[i+1] | nums[i]

        max_val = 0
        for i in range(n):
            # Apply all k operations to nums[i]
            val = nums[i] * (1 << k)
            # OR with all other elements
            if i == 0:
                rest_or = suffix_or[1] if n > 1 else 0
            elif i == n - 1:
                rest_or = prefix_or[n-2]
            else:
                rest_or = prefix_or[i-1] | suffix_or[i+1]
            total = val | rest_or
            if total > max_val:
                max_val = total

        return max_val
