class Solution:
    def minFlips(self, grid: List[List[int]]) -> int:
        m = len(grid)
        n = len(grid[0])

        # Case 1: Make all rows palindromic
        # For each row, we need to make it palindromic.
        # For a row of length n, we look at pairs (j, n-1-j) for j in range(n//2).
        # For each pair, if the two values are different, we need 1 flip.
        # If n is odd, the middle element doesn't need to be checked.
        row_flips = 0
        for i in range(m):
            for j in range(n // 2):
                if grid[i][j] != grid[i][n - 1 - j]:
                    row_flips += 1

        # Case 2: Make all columns palindromic
        # For each column, we need to make it palindromic.
        # For a column of length m, we look at pairs (i, m-1-i) for i in range(m//2).
        # For each pair, if the two values are different, we need 1 flip.
        # If m is odd, the middle element doesn't need to be checked.
        col_flips = 0
        for j in range(n):
            for i in range(m // 2):
                if grid[i][j] != grid[m - 1 - i][j]:
                    col_flips += 1

        return min(row_flips, col_flips)
