class Solution:
    def largestInteger(self, nums: List[int], k: int) -> int:
        n = len(nums)
        if k > n:
            return -1

        # For each element at index i, determine how many subarrays of size k contain it.
        # A subarray of size k starting at index s (0 <= s <= n-k) contains index i
        # if s <= i <= s + k - 1, i.e., s >= i - k + 1 and s <= i.
        # So s must be in [max(0, i - k + 1), min(i, n - k)].
        # The number of such s is min(i, n - k) - max(0, i - k + 1) + 1, if this is positive.

        count = {}
        for i in range(n):
            left = max(0, i - k + 1)
            right = min(i, n - k)
            if left <= right:
                c = right - left + 1
            else:
                c = 0
            val = nums[i]
            count[val] = count.get(val, 0) + c

        result = -1
        for val, c in count.items():
            if c == 1:
                if val > result:
                    result = val

