        # where i is the index in nums

        from functools import lru_cache

        # Precompute compatibility: can a come before b? i.e., a % b == 0 or b % a == 0
        compat = [[False] * n for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if i != j:
                    if nums[i] % nums[j] == 0 or nums[j] % nums[i] == 0:
                        compat[i][j] = True

        # dp[mask][last] where mask is a bitmask of used elements, last is the index of the last element
        # We'll use a 2D list: dp[mask][last]
        size = 1 << n
        dp = [[0] * n for _ in range(size)]

        # Base case: single element permutations
        for i in range(n):
            dp[1 << i][i] = 1

        # Fill DP
        for mask in range(size):
            for last in range(n):
                if dp[mask][last] == 0:
                    continue
                # Try to add a new element next
                for nxt in range(n):
                    if mask & (1 << nxt):
                        continue  # already used
                    if compat[last][nxt]:
                        new_mask = mask | (1 << nxt)
                        dp[new_mask][nxt] = (dp[new_mask][nxt] + dp[mask][last]) % MOD

        # Sum up all dp[full_mask][last] for all last
        full_mask = size - 1
        result = 0
        for last in range(n):
            result = (result + dp[full_mask][last]) % MOD

        return result
