class Solution:
    def beautifulNumbers(self, l: int, r: int) -> int:
        def count_beautiful(n: int) -> int:
            if n <= 0:
                return 0
            digits = list(map(int, str(n)))
            length = len(digits)

            # Use digit DP
            # State: (pos, tight, started, product, sum)
            # product can be 0 if any digit is 0, otherwise product of non-zero digits
            # We need to handle the case where product is 0 separately

            from functools import lru_cache

            @lru_cache(maxsize=None)
            def dp(pos, tight, started, product, digit_sum):
                if pos == length:
                    if not started:
                        return 0
                    # Check if product is divisible by digit_sum
                    # If product is 0, then it's divisible by any non-zero digit_sum
                    if digit_sum == 0:
                        return 0
                    if product == 0:
                        return 1
                    return 1 if product % digit_sum == 0 else 0

                limit = digits[pos] if tight else 9
                count = 0
                for d in range(limit + 1):
                    new_tight = tight and (d == limit)
                    new_started = started or (d != 0)
                    if not new_started:
                        new_product = 1  # doesn't matter, will be handled when started
                        new_sum = 0
                    else:
                        if d == 0:
                            new_product = 0
                        else:
                            new_product = product * d
                        new_sum = digit_sum + d
                    count += dp(pos + 1, new_tight, new_started, new_product, new_sum)
                return count

            return dp(0, True, False, 1, 0)

        return count_beautiful(r) - count_beautiful(l - 1)
