class Solution:
    def punishmentNumber(self, n: int) -> int:
        def can_partition(s: str, target: int) -> bool:
            # Check if string s can be partitioned into contiguous substrings
            # such that the sum of their integer values equals target
            if not s:
                return target == 0
            if target < 0:
                return False

            # Try all possible partitions
            for i in range(1, len(s) + 1):
                part = int(s[:i])
                if part > target:
                    break
                if can_partition(s[i:], target - part):
                    return True
            return False

        result = 0
        for i in range(1, n + 1):
            sq = i * i
            s = str(sq)
            if can_partition(s, i):
                result += sq
        return result
